    fx.ok("bundle carries both modules", "js/36-wall.js" in bundle and "js/38-ladder.js" in bundle)
    async with fx.browser() as b:
        pg = await fx.page(b)
        await fx.goto(pg)
        booted = await fx.wait(pg, 'self.BOOT&&BOOT.phase==="ready"', 150000)
