        fx.ok("some scene is seal-fail (tour step 5)", await pg.evaluate('S.scenes.some(s=>s.status==="seal-fail")'))
        await pg.click("#bSeal"); fx.ok("signing off again", await pg.evaluate("HASH.sealOn===false&&S.sealOn===false"))
